const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Agudo, Brazil location and 5 km buffer
  const agudoCoords = [-55.32, -29.79]; // Longitude, Latitude
  const agudoPoint = ee.Geometry.Point(agudoCoords);
  const bufferGeom = agudoPoint.buffer(5000); // 5 km radius in meters

  // 2. Define date ranges
  const date1Start = '2023-11-05';
  const date1End = '2023-11-06';
  const date2Start = '2023-11-21';
  const date2End = '2023-11-22';

  // 3. Function to mask clouds and calculate water area
  const getWaterArea = async (startDate, endDate) => {
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(bufferGeom)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

    const colSize = await col.size().getInfo();
    console.log(`Images found for ${startDate}: ${colSize}`);

    if (colSize === 0) {
      return { area: null, pixels: 0, error: 'No images found' };
    }

    // Median composite to reduce noise
    const composite = col.median();

    // Cloud masking using SCL band (Scene Classification)
    const cloudMask = composite.select('SCL').neq(3).and(composite.select('SCL').neq(8)).and(composite.select('SCL').neq(9)).and(composite.select('SCL').neq(10));
    const masked = composite.updateMask(cloudMask);

    // Calculate NDWI for water detection: (B3 - B8) / (B3 + B8)
    const ndwi = masked.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water mask: NDWI > 0.3
    const waterMask = ndwi.gt(0.3);

    // Count valid water pixels
    const pixelCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: bufferGeom,
      scale: 10, // Sentinel-2 native resolution
      maxPixels: 1e9
    }).get('NDWI').getInfo();

    // Calculate water area in km²
    const waterArea = pixelCount * 0.0001; // Each pixel is 10m x 10m = 0.01 km²

    return { area: waterArea, pixels: pixelCount, error: null };
  };

  // 4. Get water areas for both dates
  const result1 = await getWaterArea(date1Start, date1End);
  const result2 = await getWaterArea(date2Start, date2End);

  console.log(`Nov 5, 2023 - Water pixels: ${result1.pixels}, Area: ${result1.area?.toFixed(3)} km²`);
  console.log(`Nov 21, 2023 - Water pixels: ${result2.pixels}, Area: ${result2.area?.toFixed(3)} km²`);

  // 5. Validation and comparison
  if (result1.error || result2.error) {
    console.log('Error in data retrieval');
    console.log('C1');
    return;
  }

  if (result1.pixels === 0 || result2.pixels === 0) {
    console.log('No valid water pixels detected after cloud masking');
    console.log('C2');
    return;
  }

  if (result1.area === null || result2.area === null || isNaN(result1.area) || isNaN(result2.area)) {
    console.log('Calculation produced invalid result');
    console.log('C3');
    return;
  }

  // 6. Final comparison
  const areaDiff = result2.area - result1.area;
  console.log(`Area difference: ${areaDiff.toFixed(4)} km²`);

  if (areaDiff > 0.01) { // Using small threshold to account for natural variation
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
